SET NAMES utf8mb4;

ON DUPLICATE KEY UPDATE
    name = VALUES(name),
    description = VALUES(description),
    topic_audio_url = VALUES(topic_audio_url),
    display_order = VALUES(display_order),
    is_published = VALUES(is_published),
    version = VALUES(version);

ON DUPLICATE KEY UPDATE
    word = VALUES(word),
    reading = VALUES(reading),
    meaning_vi = VALUES(meaning_vi),
    part_of_speech = VALUES(part_of_speech),
    jlpt_level_id = VALUES(jlpt_level_id),
    example_sentence = VALUES(example_sentence),
    example_reading = VALUES(example_reading),
    example_meaning_vi = VALUES(example_meaning_vi),
    display_order = VALUES(display_order),
    is_published = VALUES(is_published),
    version = VALUES(version);
